#!/usr/bin/env python3

import os
import xml.etree.ElementTree as ET

import numpy as np
import rclpy
from ament_index_python.packages import get_package_share_directory
from rclpy.node import Node
from sensor_msgs.msg import JointState

# Import the product of exponentials function from your HW2 code
from forward_kinematics.kin_func_skeleton import forward_kinematics

JOINT_NAMES = [
    "shoulder_pan_joint",
    "shoulder_lift_joint",
    "elbow_joint",
    "wrist_1_joint",
    "wrist_2_joint",
    "wrist_3_joint",
]


class ForwardKinematicsNode(Node):
    def __init__(self):
        super().__init__("forward_kinematics_node")

        self.twists, self.gst0 = self.load_kinematics_description()

        self.subscription = self.create_subscription(
            JointState,
            "/joint_states",
            self.joint_state_callback,
            10,
        )

        self.get_logger().info("Forward kinematics node started.")

    def load_kinematics_description(self):
        """
        Load q_i, omega_i, and g_st(0) from the provided flattened
        UR7e kinematics description.

        Returns:
            twists: (6, 6) ndarray with one twist per column
            gst0: (4, 4) ndarray
        """

        package_share = get_package_share_directory("forward_kinematics")
        path = os.path.join(package_share, "urdf", "ur7e_flattened.urdf")

        root = ET.parse(path).getroot()

        joints = {j.attrib["name"]: j for j in root.findall("joint")}

        # joint_data: list of (q, omega)
        joint_data = []
        for name in JOINT_NAMES:
            joint = joints[name]
            q = np.fromstring(joint.find("origin").attrib["xyz"], sep=" ")
            omega = np.fromstring(joint.find("axis").attrib["xyz"], sep=" ")
            joint_data.append((q, omega))

        zero_config = root.find("zero_configuration")

        # R: (3, 3) ndarray
        R = np.array(
            [
                np.fromstring(row.attrib["values"], sep=" ")
                for row in zero_config.find("rotation").findall("row")
            ]
        )

        # p: (3,) ndarray
        p = np.fromstring(
            zero_config.find("translation").attrib["xyz"],
            sep=" ",
        )

        # Construct each 6D twist xi_i = [-omega_i x q_i, omega_i]^T
        twist_list = []
        for q, omega in joint_data:
            v = -np.cross(omega, q)
            xi = np.concatenate([v, omega])  # 6D vector
            twist_list.append(xi)

        # Stack twists into a (6, 6) ndarray (one twist per column)
        twists = np.column_stack(twist_list)

        # Construct g_st(0) as a 4x4 homogeneous matrix
        gst0 = np.eye(4)
        gst0[:3, :3] = R
        gst0[:3, 3] = p

        return twists, gst0

    def joint_state_callback(self, msg):
        """
        Compute g_st(theta) whenever a new JointState message arrives.
        """
        # Map joint names to positions to account for arbitrary topic ordering
        joint_map = dict(zip(msg.name, msg.position))

        # Extract joint angles theta in the exact order of JOINT_NAMES
        theta = np.array([joint_map[name] for name in JOINT_NAMES])

        # Evaluate product of exponentials: e^(hat(xi_1)*theta_1) ... e^(hat(xi_6)*theta_6)
        exp_product = forward_kinematics(self.twists, theta)

        # Compute full forward kinematics matrix g_st(theta) = FK(xi, theta) * g_st(0)
        gst_theta = exp_product @ self.gst0

        # Log or print the resulting 4x4 matrix
        self.get_logger().info(
            f"\nComputed g_st(theta):\n{np.array2string(gst_theta, precision=4, suppress_small=True)}"
        )


def main(args=None):
    rclpy.init(args=args)

    node = ForwardKinematicsNode()

    try:
        rclpy.spin(node)
    except KeyboardInterrupt:
        pass

    node.destroy_node()
    rclpy.shutdown()


if __name__ == "__main__":
    main()